]

def has_neighbor_4(grid, r, c):
    val = grid[r][c]
    if val == 5:
        return False
    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    rows, cols = len(grid), len(grid[0])
    for dr, dc in directions:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            if grid[nr][nc] == val:
                return True
    return False

output_keep_special = []
for r in range(8):
    row_out = []
    for c in range(12):
        if has_neighbor_4(input_grid, r, c):
            row_out.append(input_grid[r][c])  # keep original value
        else:
            row_out.append(0)  # replace with 0
    output_keep_special.append(row_out)

print("Output (keep special cells, 0 elsewhere):")
for row in output_keep_special:
    print(row)

